query:
MATCH (holder:Organization {id: 'lumen'})-[:HOLDS]->(patent:Patent)<-[:USES_PATENT]-(site:Site)-[:ESTABLISHED_UNDER]->(project:Project)
CALL (site) {
  MATCH (operator:Organization)-[:OPERATES]->(site)
  WITH operator ORDER BY operator.name
  RETURN collect(operator.name) AS operators
}
CALL (patent) {
  MATCH (inventor:Researcher)-[:INVENTED]->(patent)
  WITH inventor ORDER BY inventor.name
  RETURN collect(inventor.name) AS inventors
}
CALL (patent) {
  MATCH (patent)-[:LICENSED_IN]->(licensed:Project)
  WITH licensed ORDER BY licensed.name
  RETURN collect(licensed.name) AS patent_licensed_in
}
RETURN site.name AS site, project.name AS project, patent.id AS patent, holder.name AS patent_holder, operators, inventors, patent_licensed_in
ORDER BY site
